const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const damiettaMouth = ee.Geometry.Polygon(
    [[[31.75, 31.5],
      [31.9, 31.5],
      [31.9, 31.6],
      [31.75, 31.6],
      [31.75, 31.5]]], null, false);

  const year1 = '1984';
  const startDate1 = `${year1}-06-01`;
  const endDate1 = `${year1}-09-30`; // Peak vegetation period

  const year2 = '2021';
  const startDate2 = `${year2}-06-01`;
  const endDate2 = `${year2}-09-30`; // Peak vegetation period

  const scale = 300; // Increased scale to avoid memory issues and speed up.

  // Function to mask clouds from Landsat 5 SR data.
  function maskL5sr(image) {
    const qa = image.select('QA_PIXEL');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitmask = (1 << 3);
    const cloudsBitmask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitmask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitmask).eq(0));
    return image.updateMask(mask).select('SR_B1', 'SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B7')
                .copyProperties(image, ['system:time_start']);
  }

  // Function to mask clouds from Landsat 8 SR data.
  function maskL8sr(image) {
    const qa = image.select('QA_PIXEL');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitmask = (1 << 3);
    const cloudsBitmask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitmask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitmask).eq(0));
    return image.updateMask(mask).select('SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7')
                .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDVI.
  function addNdvi(image, redBand, nirBand) {
    const ndvi = image.normalizedDifference([nirBand, redBand]).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 2. Data Acquisition & Check for 1984 (Landsat 5)
  let collection1 = ee.ImageCollection('USGS/LT05/C02/SR')
    .filterBounds(damiettaMouth)
    .filterDate(startDate1, endDate1)
    .map(maskL5sr)
    .map(img => addNdvi(img, 'SR_B3', 'SR_B4')); // L5: Red B3, NIR B4

  if (await collection1.size().getInfo() === 0) {
    console.log(`No images found for ${year1}.`);
    console.log("C1");
    return;
  }

  // 2. Data Acquisition & Check for 2021 (Landsat 8)
  let collection2 = ee.ImageCollection('USGS/LC08/C02/SR')
    .filterBounds(damiettaMouth)
    .filterDate(startDate2, endDate2)
    .map(maskL8sr)
    .map(img => addNdvi(img, 'SR_B4', 'SR_B5')); // L8: Red B4, NIR B5

  if (await collection2.size().getInfo() === 0) {
    console.log(`No images found for ${year2}.`);
    console.log("C1");
    return;
  }

  // Get median NDVI image for each period
  const medianNdvi1 = collection1.median().select('NDVI');
  const medianNdvi2 = collection2.median().select('NDVI');

  // 3. Processing & Pixel Count Check for 1984
  const count1 = await medianNdvi1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: damiettaMouth,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count1 === 0) {
    console.log(`No valid pixels remaining for ${year1} after masking.`);
    console.log("C2");
    return;
  }

  // 3. Processing & Pixel Count Check for 2021
  const count2 = await medianNdvi2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: damiettaMouth,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count2 === 0) {
    console.log(`No valid pixels remaining for ${year2} after masking.`);
    console.log("C2");
    return;
  }

  // 4. Calculation - Mean NDVI for each period
  const ndvi1984 = await medianNdvi1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: damiettaMouth,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const ndvi2021 = await medianNdvi2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: damiettaMouth,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 5. Validation & Final Answer
  if (ndvi1984 === null || isNaN(ndvi1984) || ndvi2021 === null || isNaN(ndvi2021)) {
    console.log("Calculation resulted in invalid values (null or NaN).");
    console.log("C3");
    return;
  }

  console.log(`1984 Images: ${await collection1.size().getInfo()} (Pixels: ${count1})`);
  console.log(`2021 Images: ${await collection2.size().getInfo()} (Pixels: ${count2})`);
  console.log(`Mean NDVI ${year1}: ${ndvi1984.toFixed(3)}`);
  console.log(`Mean NDVI ${year2}: ${ndvi2021.toFixed(3)}`);

  if (ndvi1984 > ndvi2021) {
    console.log("A"); // Yes, 1984 was greater.
  } else {
    console.log("B"); // No, 1984 was not greater.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
